import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int a = in.nextInt();
        int b = in.nextInt();
        String kesadi = Math.abs(a - b) <= 4 ? "yes" : "no";
        System.out.println((2407 + 5 * a) + " " + (2407 + 5 * b) + " " + kesadi);
    }
}

